using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the API key via 'AI:ApiKey' in config or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddHostedService<ResearchWorker>();

var app = builder.Build();
await app.RunAsync();

/// <summary>Tools the research agent can invoke during its investigation loop.</summary>
public sealed class ResearchTools
{
    private readonly List<(string Query, string Result)> _notes = [];

    [Description("Search the web for information on a query. Returns a summary of top results.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulate network latency
        await Task.Delay(250);

        // In production, wire this to Bing Search API, Google Custom Search, etc.
        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("climate change") =>
                """
                1. NASA: Global temperatures have risen ~1.1°C since the pre-industrial era, driven largely by CO₂ emissions.
                2. IPCC AR6 (2023): Limiting warming to 1.5°C requires a 43% reduction in emissions by 2030.
                3. NOAA: 2023 was the warmest year on record; ocean heat content hit an all-time high.
                4. Nature (2024): Tipping points for ice-sheet collapse may be closer than previously estimated.
                """,
            var q when q.Contains("artificial intelligence") || q.Contains(" ai ") || q.Contains("machine learning") =>
                """
                1. Stanford HAI Index (2024): Global AI investment exceeded $90B; generative AI funding tripled YoY.
                2. OpenAI, Anthropic, and Google DeepMind released frontier models with improved reasoning benchmarks.
                3. EU AI Act entered provisional agreement — risk-based regulation framework for AI systems.
                4. McKinsey (2024): ~60% of occupations have tasks automatable with current AI technology.
                """,
            var q when q.Contains("quantum computing") =>
                """
                1. IBM unveiled a 1,121-qubit processor (Condor) and a modular architecture roadmap to 100k qubits.
                2. Google's Willow chip demonstrated error correction below the fault-tolerance threshold.
                3. Practical quantum advantage remains 5-10 years away for most commercial applications.
                4. NIST post-quantum cryptography standards were finalized in 2024.
                """,
            _ =>
                $"""
                 1. Wikipedia summary: '{query}' is a broad research area with active development.
                 2. Recent scholarly articles discuss emerging trends related to '{query}'.
                 3. Industry analysts project significant growth in '{query}'-related sectors.
                 """
        };

        Console.WriteLine($"  🔍  Searched: \"{query}\"");
        return results;
    }

    [Description("Save a research note. Use this to record key findings you want to include in the final summary.")]
    public string SaveNote(
        [Description("A concise research note capturing a key finding")] string note)
    {
        _notes.Add((DateTime.UtcNow.ToString("HH:mm:ss"), note));
        Console.WriteLine($"  📝  Note saved ({_notes.Count} total)");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] ({n.Query}) {n.Result}"));
    }
}

/// <summary>Background worker that runs the agent research loop.</summary>
public sealed class ResearchWorker(
    IChatClient chatClient,
    ResearchTools tools,
    IHostApplicationLifetime lifetime) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════════╗");
        Console.WriteLine("║       🔬  Research Agent  🔬        ║");
        Console.WriteLine("╚══════════════════════════════════════╝");
        Console.Write("\nEnter a research topic: ");
        var topic = Console.ReadLine()?.Trim();

        if (string.IsNullOrEmpty(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: \"{topic}\"\n");

        var agent = new ChatClientAgent(chatClient, "ResearchAgent")
        {
            Description = "An AI research assistant that investigates topics by searching the web and taking notes.",
            Instructions =
                """
                You are a thorough research assistant. Given a topic, you must:
                1. Search the web multiple times with different queries to gather diverse information.
                2. Save important findings as notes using the SaveNote tool.
                3. After collecting enough information, retrieve your notes with GetNotes.
                4. Provide a well-structured summary with key findings, organized by theme.

                Always perform at least 2-3 searches before summarizing. Be specific in your queries.
                """,
        };

        var agentOptions = new AgentInvokeOptions
        {
            MaximumIterations = 10,
        };

        var chatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. AIFunctionFactory.Create(tools)],
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User,
                $"Research the following topic thoroughly and provide a comprehensive summary: {topic}"),
        };

        Console.WriteLine("Agent is working...\n");

        string? finalResponse = null;

        await foreach (var message in agent.InvokeStreamingAsync(
            history, chatOptions, agentOptions, stoppingToken))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                finalResponse = message.Text;
            }
        }

        Console.WriteLine("\n══════════════ RESEARCH SUMMARY ══════════════\n");
        Console.WriteLine(finalResponse ?? "Agent did not produce a summary.");
        Console.WriteLine("\n══════════════════════════════════════════════\n");

        lifetime.StopApplication();
    }
}

